        function toggleCategory(header) {
            const category = header.parentElement;
            category.classList.toggle('expanded');
        }

        function copyToClipboard(button) {
            const promptText = button.parentElement.nextElementSibling.textContent;

            if (navigator.clipboard && window.isSecureContext) {
                navigator.clipboard.writeText(promptText).then(() => {
                    showNotification();
                }).catch(err => {
                    fallbackCopyTextToClipboard(promptText);
                });
            } else {
                fallbackCopyTextToClipboard(promptText);
            }
        }

        function fallbackCopyTextToClipboard(text) {
            const textArea = document.createElement("textarea");
            textArea.value = text;
            textArea.style.top = "0";
            textArea.style.left = "0";
            textArea.style.position = "fixed";
            document.body.appendChild(textArea);
            textArea.focus();
            textArea.select();

            try {
                document.execCommand('copy');
                showNotification();
            } catch (err) {
                console.error('Fallback: Oops, unable to copy', err);
            }

            document.body.removeChild(textArea);
        }

        function showNotification() {
            const notification = document.getElementById('notification');
            notification.classList.add('show');
            setTimeout(() => {
                notification.classList.remove('show');
            }, 2000);
        }

        // Search and filter functionality
        const searchBox = document.getElementById('searchBox');
        const filterButtons = document.querySelectorAll('.filter-btn');

        searchBox.addEventListener('input', function() {
            filterPrompts();
        });

        filterButtons.forEach(btn => {
            btn.addEventListener('click', function() {
                filterButtons.forEach(b => b.classList.remove('active'));
                this.classList.add('active');
                filterPrompts();
            });
        });

        function filterPrompts() {
            const searchTerm = searchBox.value.toLowerCase();
            const activeFilter = document.querySelector('.filter-btn.active').dataset.filter;
            const categories = document.querySelectorAll('.category');
            let visibleCount = 0;

            categories.forEach(category => {
                const genre = category.dataset.genre;
                const categoryTitle = category.querySelector('.category-title').textContent.toLowerCase();
                const promptItems = category.querySelectorAll('.prompt-item');
                let hasVisibleItems = false;

                // Check if category matches filter
                const matchesFilter = activeFilter === 'all' || 
                    genre === activeFilter ||
                    (activeFilter === 'metal' && (genre === 'metal' || genre === 'doom-stoner'));

                promptItems.forEach(item => {
                    const promptTitle = item.querySelector('.prompt-title').textContent.toLowerCase();
                    const promptText = item.querySelector('.prompt-text').textContent.toLowerCase();

                    const matchesSearch = searchTerm === '' || 
                        promptTitle.includes(searchTerm) || 
                        promptText.includes(searchTerm) || 
                        categoryTitle.includes(searchTerm);

                    if (matchesFilter && matchesSearch) {
                        item.classList.remove('hidden');
                        hasVisibleItems = true;
                        visibleCount++;
                    } else {
                        item.classList.add('hidden');
                    }
                });

                if (hasVisibleItems && matchesFilter) {
                    category.classList.remove('hidden');
                    if (searchTerm !== '' || activeFilter !== 'all') {
                        category.classList.add('expanded');
                    }
                } else {
                    category.classList.add('hidden');
                }
            });

            updateStats(visibleCount);
        }

        // Initialize
        document.addEventListener('DOMContentLoaded', function() {
            updateStats();
            // Expand first category by default
            const firstCategory = document.querySelector('.category');
            if (firstCategory) {
                firstCategory.classList.add('expanded');
            }
        });
    </script>
